def zcomps(A,diag=False):
 R,C=len(A),len(A[0]); seen=set(); comps=[]
 ds=[(1,0),(-1,0),(0,1),(0,-1)]
 if diag: ds += [(1,1),(1,-1),(-1,1),(-1,-1)]
 for r in range(R):
  for c in range(C):
   if A[r][c]==0 and (r,c) not in seen:
    q=[(r,c)];seen.add((r,c)); comp=[]
    for x,y in q:
     comp.append((x,y))
     for dr,dc in ds:
      a,b=x+dr,y+dc
      if 0<=a<R and 0<=b<C and A[a][b]==0 and (a,b) not in seen:seen.add((a,b));q.append((a,b))
    comps.append(comp)
 return comps
